namespace tunuino {
struct ScatterPoint {double x,y,z,seconds;};
class ScatterCanvas final:public QWidget {
public:explicit ScatterCanvas(QWidget *parent):QWidget(parent){setObjectName("scatterCanvas");setMinimumSize(180,140);}
 QVector<ScatterPoint> points;std::array<std::pair<double,double>,3> ranges{{{0,1},{0,1},{0,1}}};std::array<int,3> channels{{0,2,3}};int pointSize=3;
protected:
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#202326"));const QRectF area=QRectF(rect()).adjusted(70,24,-80,-50);if(area.width()<=0||area.height()<=0)return;p.setPen(QColor("#53595b"));for(int i=0;i<=5;++i){double x=area.left()+area.width()*i/5,y=area.bottom()-area.height()*i/5;p.drawLine(QPointF(x,area.top()),QPointF(x,area.bottom()));p.drawLine(QPointF(area.left(),y),QPointF(area.right(),y));p.setPen(QColor("#dce2d9"));double xv=ranges[0].first+(ranges[0].second-ranges[0].first)*i/5,yv=ranges[1].first+(ranges[1].second-ranges[1].first)*i/5;p.drawText(QRectF(x-32,area.bottom()+4,64,20),Qt::AlignCenter,QString::number(displayValue(channels[0],xv),'g',5));p.drawText(QRectF(2,y-10,62,20),Qt::AlignRight,QString::number(displayValue(channels[1],yv),'g',5));p.setPen(QColor("#53595b"));}p.save();p.setClipRect(area);p.setPen(Qt::NoPen);for(const auto &v:points){const double x=area.left()+(v.x-ranges[0].first)/(ranges[0].second-ranges[0].first)*area.width(),y=area.bottom()-(v.y-ranges[1].first)/(ranges[1].second-ranges[1].first)*area.height();const double z=channels[2]>=0?qBound(0.,(v.z-ranges[2].first)/(ranges[2].second-ranges[2].first),1.):.5;p.setBrush(channels[2]>=0?QColor::fromHsvF(.66*(1-z),.85,.95):QColor("#36b5ef"));p.drawEllipse(QPointF(x,y),pointSize/2.,pointSize/2.);}p.restore();p.setPen(QColor("#e1e7dd"));p.drawText(QRectF(area.left(),height()-25,area.width(),22),Qt::AlignCenter,label(0));p.save();p.translate(17,area.center().y());p.rotate(-90);p.drawText(QRectF(-area.height()/2,-12,area.height(),24),Qt::AlignCenter,label(1));p.restore();if(channels[2]>=0){QRectF colorBar(area.right()+12,area.top(),12,area.height());QLinearGradient g(colorBar.bottomLeft(),colorBar.topLeft());for(int i=0;i<=6;++i)g.setColorAt(i/6.,QColor::fromHsvF(.66*(1-i/6.),.85,.95));p.fillRect(colorBar,g);p.drawText(QRectF(colorBar.right()+3,area.top(),50,20),QString::number(displayValue(channels[2],ranges[2].second),'g',4));p.drawText(QRectF(colorBar.right()+3,area.bottom()-18,50,20),QString::number(displayValue(channels[2],ranges[2].first),'g',4));p.drawText(QRectF(area.right()-60,1,130,20),Qt::AlignCenter,label(2));}if(points.isEmpty())p.drawText(area,Qt::AlignCenter,tr("No valid recorded samples in this range"));}
 void mousePressEvent(QMouseEvent *event)override{const QRectF area=QRectF(rect()).adjusted(70,24,-80,-50);double best=144;const ScatterPoint *found=nullptr;for(const auto &v:points){QPointF pos(area.left()+(v.x-ranges[0].first)/(ranges[0].second-ranges[0].first)*area.width(),area.bottom()-(v.y-ranges[1].first)/(ranges[1].second-ranges[1].first)*area.height());const auto d=pos-event->position();double dist=d.x()*d.x()+d.y()*d.y();if(dist<best){best=dist;found=&v;}}setToolTip(found?tr("Time %1 s; X %2; Y %3; Z %4").arg(found->seconds).arg(displayValue(channels[0],found->x)).arg(displayValue(channels[1],found->y)).arg(channels[2]>=0?QString::number(displayValue(channels[2],found->z)):tr("None")):QString{});}
private:QString label(int i)const{return channels[i]>=0?QString::fromLatin1(LogNames[channels[i]])+" ["+displayUnit(channels[i],LogUnits[channels[i]])+"]":tr("None");}
};
class ScatterPlotWidget final:public QWidget {
public:
 explicit ScatterPlotWidget(GraphLogWidget *log,QWidget *parent=nullptr):QWidget(parent),log_(log){setObjectName("scatterPlot");auto *layout=new QVBoxLayout(this);layout->setContentsMargins(4,4,4,4);auto *bar=SensorUi::toolbar(this);auto *config=bar->addAction(style()->standardIcon(QStyle::SP_FileDialogDetailedView),tr("Scatter Plot configuration"));config->setObjectName("scatterConfigure");connect(config,&QAction::triggered,this,[this]{configure();});layout->addWidget(bar);canvas_=new ScatterCanvas(this);layout->addWidget(canvas_,1);state_=new QLabel(this);layout->addWidget(state_);QSettings s;std::array<int,3> c{{s.value("scatter/x",0).toInt(),s.value("scatter/y",2).toInt(),s.value("scatter/z",3).toInt()}},f{{s.value("scatter/filter0",1).toInt(),s.value("scatter/filter1",1).toInt(),s.value("scatter/filter2",1).toInt()}};setConfiguration(c,f,s.value("scatter/size",3).toInt(),false);auto *timer=new QTimer(this);connect(timer,&QTimer::timeout,this,[this]{if(isVisible())rebuild();});timer->start(250);rebuild();}
 bool setConfiguration(const std::array<int,3>&channels,const std::array<int,3>&filters,int size,bool save=true){for(int i=0;i<3;++i)if(channels[i]<(i==2?-1:0)||channels[i]>=LogChannelCount||filters[i]<1||filters[i]>1000)return false;if(size<1||size>10)return false;canvas_->channels=channels;filters_=filters;canvas_->pointSize=size;if(save){QSettings s;s.setValue("scatter/x",channels[0]);s.setValue("scatter/y",channels[1]);s.setValue("scatter/z",channels[2]);for(int i=0;i<3;++i)s.setValue(QString("scatter/filter%1").arg(i),filters[i]);s.setValue("scatter/size",size);}revision_=quint64(-1);rebuild();return true;}
 const QVector<ScatterPoint> &points()const{return canvas_->points;}
 void rebuild(){const auto &view=log_->view();std::array<std::pair<double,double>,3> ranges;for(int i=0;i<3;++i)ranges[i]=canvas_->channels[i]>=0?log_->axisRange(canvas_->channels[i]):std::pair<double,double>{0,1};if(revision_==log_->revision()&&begin_==view.selectionBegin&&end_==view.selectionEnd&&ranges==canvas_->ranges)return;revision_=log_->revision();begin_=view.selectionBegin;end_=view.selectionEnd;canvas_->ranges=ranges;canvas_->points.clear();std::array<std::deque<double>,3> windows;std::array<double,3> sums{};for(const auto &s:log_->samples()){if(begin_>=0&&end_>=0&&(s.seconds<std::min(begin_,end_)||s.seconds>std::max(begin_,end_)))continue;std::array<double,3> v;bool valid=true;for(int i=0;i<3;++i){if(canvas_->channels[i]<0){v[i]=0;continue;}const double raw=s.values[canvas_->channels[i]];if(!std::isfinite(raw)){windows[i].clear();sums[i]=0;valid=false;v[i]=raw;continue;}windows[i].push_back(raw);sums[i]+=raw;if(windows[i].size()>size_t(filters_[i])){sums[i]-=windows[i].front();windows[i].pop_front();}v[i]=sums[i]/windows[i].size();}if(valid)canvas_->points.append({v[0],v[1],v[2],s.seconds});}state_->setText(tr("%1 recorded points | %2 | ranges from Graph Log | no ECU writes").arg(canvas_->points.size()).arg(begin_>=0&&end_>=0?tr("selected interval %1–%2 s").arg(std::min(begin_,end_)).arg(std::max(begin_,end_)):tr("complete log")));canvas_->update();}
private:
 void configure(){QDialog dialog(this);dialog.setWindowTitle(tr("Scatter Plot configuration"));auto *layout=new QVBoxLayout(&dialog);auto *table=new QTableWidget(7,2,&dialog);SensorUi::grid(table);layout->addWidget(table);std::array<QComboBox*,3> channels;std::array<QDoubleSpinBox*,3> filters;for(int i=0;i<3;++i){table->setItem(i,0,new QTableWidgetItem(QString("%1 Axis channel").arg(QChar('X'+i))));auto *combo=new QComboBox(table);if(i==2)combo->addItem(tr("None"),-1);for(int c=0;c<LogChannelCount;++c)combo->addItem(LogNames[c],c);combo->setCurrentIndex(combo->findData(canvas_->channels[i]));SensorUi::choices(combo);table->setCellWidget(i,1,combo);channels[i]=combo;table->setItem(3+i,0,new QTableWidgetItem(QString("%1 Axis filter samples").arg(QChar('X'+i))));auto *spin=new QDoubleSpinBox(table);spin->setDecimals(0);spin->setRange(1,1000);spin->setValue(filters_[i]);table->setCellWidget(3+i,1,spin);filters[i]=spin;}table->setItem(6,0,new QTableWidgetItem(tr("Point size")));auto *size=new QDoubleSpinBox(table);size->setRange(1,10);size->setDecimals(0);size->setValue(canvas_->pointSize);table->setCellWidget(6,1,size);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,&dialog);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(480,350);if(dialog.exec()==QDialog::Accepted)setConfiguration({{channels[0]->currentData().toInt(),channels[1]->currentData().toInt(),channels[2]->currentData().toInt()}},{{int(filters[0]->value()),int(filters[1]->value()),int(filters[2]->value())}},int(size->value()));}
 GraphLogWidget *log_;ScatterCanvas *canvas_;QLabel *state_;std::array<int,3> filters_{{1,1,1}};quint64 revision_=quint64(-1);double begin_=-2,end_=-2;
};
}
